function openModal(html,wide=false){$('#modalContent').innerHTML=html;$('.modal__paper').style.width=wide?'min(820px,96vw)':'';$('#modal').classList.add('open');$('#modal').setAttribute('aria-hidden','false')}
function closeModal(){$('#modal').classList.remove('open');$('#modal').setAttribute('aria-hidden','true')}
function journeyTracker(){let n=S.completedGamesThisCycle.length,points=Array.from({length:5},(_,i)=>`<i class="journey-point ${i<n?'is-done':''} ${i===n&&n<5?'is-current':''}"></i>`).join('');return `<div class="jade-tracker" role="img" aria-label="Нефритовый путь: пройдено ${n} из 5 игр" data-tooltip="Пройди 5 игр — получи награду."><img class="jade-traveler" style="--journey-step:${n}" src="assets/ui/jade-guardian.png" alt=""><span class="jade-road">${points}</span><span class="jade-palace" aria-hidden="true"><img src="assets/ui/header/progress-tracker-palace.png" alt=""></span></div>`}
function shell(content){return `<header class="top paper"><button class="logo" data-view="home"><img class="header-red-seal" src="assets/ui/header/header-red-seal.png" alt=""><span>Нефритовый путь</span></button>${journeyTracker()}<div class="top__tools">${soundButton()}</div></header>${content}<nav class="bottom"><i class="bottom__ornament" aria-hidden="true"></i><i class="bottom__corner bottom__corner--left" aria-hidden="true"></i><button data-info="history"><img class="nav-image nav-image--lantern" src="assets/ui/home/nav-history-lantern.png" alt=""><span><b>Легенда</b></span></button><button data-info="dictionary"><img class="nav-image nav-image--book" src="assets/ui/home/nav-dictionary-book.png" alt=""><span><b>Словарь</b></span></button><button data-info="rewards"><img class="nav-image nav-image--reward" src="assets/ui/home/nav-awards-pendant.png" alt=""><span><b>Награды</b></span></button><i class="bottom__corner bottom__corner--right" aria-hidden="true"></i></nav>`}
function render(){prepareSilhouetteAtlas();if(S.view==='home')home();else if(S.view==='collection')collection();else gameShell()}
function home(){S.view='home';const labels=['⚑ 24 испытания','◆ Головоломка','◐ Узнай по тени','⌕ Поиск слов','文 Составь фразу'],limits=[5,3,3,3,5];let games=G.map((g,i)=>{let lives=i===0?S.lives:(S.game===i&&S.gameLives?S.gameLives.current:limits[i]);let figures=Array.from({length:lives},()=>`<img src="assets/ui/jade-guardian.png" alt="">`).join('');return `<article class="game-tile game-tile--${i+1}"><div class="game-tile__preview"><img class="game-tile__image" src="${g[2]}" alt="${g[0]}"><span class="game-number">${i+1}</span><button class="play-arrow" data-game="${i}" aria-label="Играть: ${g[0]}"><img src="assets/ui/home/cards/game-play-button.png" alt="" aria-hidden="true"></button></div><div class="game-tile__body"><h2>${g[0]}</h2><p>${labels[i]}</p><div class="preview-lives" aria-label="Осталось ${lives} жизней"><b>Жизни</b><span aria-hidden="true">${figures}</span></div></div></article>`}).join('');$('#app').innerHTML=shell(`<section class="hero"><p class="hero__cn">十二生肖的旅程</p><h1>Путешествие животных к Императору</h1></section><main class="home"><section class="game-grid">${games}<button class="collection-home-tile paper" data-view="collection"><div class="collection-home-tile__preview"><img class="collection-home-tile__image" src="assets/games/collection.png" alt="Коллекция китайского зодиака"></div><div class="collection-home-tile__body"><h2>Коллекция зодиака</h2><p>Собрано ${S.opened.length} из 12</p></div></button></section></main>`)}
function roadStartScreen(){let selected=S.roadCandidate,animals=A.map(a=>`<button class="road-companion ${selected?.i===a.i?'is-selected':''}" data-road-candidate="${a.i}" aria-label="Выбрать: ${a.ru}, ${a.pinyin}" aria-pressed="${selected?.i===a.i}">${animalArt(a,'road-companion__art')}<span><b>${a.hanzi}</b><i>${a.pinyin}</i></span><small>${a.ru}</small><em aria-hidden="true">✓</em></button>`).join(''),chosen=selected?`<b>${selected.hanzi}</b><i>${selected.pinyin}</i><span>${selected.ru}</span>`:'<span>— выбери животное —</span>',lives=Array.from({length:S.lives},()=>`<img src="assets/ui/jade-guardian.png" alt="">`).join('');$('#app').innerHTML=`<main class="road-start"><header class="road-start__top"><button class="road-start__brand start-exit" data-view="home" aria-label="Выйти на главную">← Выйти</button><h1><i aria-hidden="true"></i>Дорога к Императору<i aria-hidden="true"></i></h1>${soundButton()}</header><div class="road-start__spread"><section class="road-start__legend"><img src="assets/games/road-to-emperor.png" alt="Дорога через горы к дворцу Нефритового Императора"><p>Нефритовый император созвал двенадцать животных во дворец. Каждому предстоит долгий путь, полный испытаний. Выбери спутника, преодолей вместе с ним <b>24</b> препятствия и помоги ему добраться до Императора.</p></section><section class="road-start__choice"><h2>Выбери своего спутника</h2><div class="road-companions">${animals}</div><footer class="road-start__summary"><div class="road-start__details"><p><strong>Твой спутник:</strong><span class="road-start__selected">${chosen}</span></p><p><strong>Жизни:</strong><span class="road-start__lives" aria-label="Осталось ${S.lives} жизней">${lives}</span></p></div><button class="road-start__go" data-road-begin ${selected?'':'disabled'} aria-label="Начать путешествие с выбранным спутником"><span>В путь</span><i aria-hidden="true">→</i></button></footer></section></div></main>`}
function roadGameScreen(){$('#app').innerHTML=`<main class="road-game"><header class="road-game__top"><button class="road-game__exit" data-view="home">← Выйти</button><h1><i aria-hidden="true"></i>Дорога к Императору<i aria-hidden="true"></i></h1>${soundButton()}${roadLives()}</header><div class="road-game__layout"><section id="gameStage" class="road-game__stage"></section><div class="road-first-hint"><b>灯</b><span>Нажми на текущую точку пути, чтобы начать испытание.</span></div></div><aside id="roadTaskPanel" class="road-task-panel" role="dialog" aria-modal="true" aria-live="polite"></aside><input id="roadCheck" type="hidden" disabled></main>`;road();startMusic()}
function sudokuStartScreen(){let selected=S.sudokuModeCandidate,modes=[['easy','Лёгкий','Изображения животных',`<span class="sudoku-mode-preview sudoku-mode-preview--animals">${A.slice(0,4).map(a=>animalArt(a,'sudoku-mode-animal')).join('')}</span>`],['medium','Средний','Иероглифы с пиньинем','<span class="sudoku-mode-preview"><b>兔</b><i>tù</i></span>'],['hard','Сложный','Только иероглифы','<span class="sudoku-mode-preview"><b>兔</b></span>']],cards=modes.map(m=>`<button class="sudoku-mode-card ${selected===m[0]?'is-selected':''}" data-sudoku-mode="${m[0]}" aria-pressed="${selected===m[0]}">${m[3]}<span><b>${m[1]}</b><small>${m[2]}</small></span><em aria-hidden="true">✓</em></button>`).join(''),lives=Array.from({length:S.gameLives?.current||3},()=>`<img src="assets/ui/jade-guardian.png" alt="">`).join(''),level=modes.find(m=>m[0]===selected)?.[1]||'— выбери уровень —';$('#app').innerHTML=`<main class="sudoku-start"><header class="sudoku-start__top"><button class="sudoku-start__brand start-exit" data-view="home" aria-label="Выйти на главную">← Выйти</button>${soundButton()}</header><div class="sudoku-start__heading"><h1>Зодиак-судоку</h1><p>Разгадай узор и сними заклятие с моста.</p></div><div class="sudoku-start__layout"><section class="sudoku-start__story"><figure><img src="assets/games/sudoku-intro-bridge.png" alt="Заколдованный мост с исчезнувшими плитами и горным духом"></figure><p>Горный дух заколдовал мост: перемешал знаки животных, а некоторые плиты сделал невидимыми.<br>Верни каждый знак на своё место — заполни пустые клетки без повторов в строках и столбцах. Тогда заклятие исчезнет и мост снова откроется.</p></section><section class="sudoku-start__choice"><h2>Выбери уровень</h2><div class="sudoku-mode-cards">${cards}</div><footer><div><p><b>Твой уровень:</b><span>${level}</span></p><p><b>Жизни:</b><span class="sudoku-start__lives" aria-label="Три жизни">${lives}</span></p></div><button class="sudoku-start__go" data-sudoku-begin ${selected?'':'disabled'}>В путь <i>→</i></button></footer></section></div></main>`}
function sudokuGameScreen(){$('#app').innerHTML=`<main class="sudoku-game"><header class="sudoku-game__top"><button class="sudoku-game__exit" data-view="home">← Выйти</button><div><h1>Зодиак-судоку</h1><p>Разгадай узор и сними заклятие с моста.</p></div>${soundButton()}</header><section id="gameStage" class="sudoku-game__stage"></section></main>`;sudoku();startMusic()}
function findStartScreen(){let selected=S.findModeCandidate,modes=[['easy','词','Лёгкий','Поле 6×6, пиньинь и прямые слова'],['hard','字','Сложный','Диагонали и ложные сочетания']],cards=modes.map(m=>`<button class="find-mode-card ${selected===m[0]?'is-selected':''}" data-find-mode="${m[0]}" aria-pressed="${selected===m[0]}"><strong>${m[1]}</strong><span><b>${m[2]}</b><small>${m[3]}</small></span><em aria-hidden="true">✓</em></button>`).join(''),level=modes.find(m=>m[0]===selected)?.[2]||'— выбери уровень —',lives=Array.from({length:S.gameLives?.current||3},()=>`<img src="assets/ui/jade-guardian.png" alt="">`).join('');$('#app').innerHTML=`<main class="find-start"><header class="find-start__top"><button class="find-start__home start-exit" data-view="home" aria-label="Выйти на главную">← Выйти</button><div><h1>Секретный код</h1><p>Найди спрятанные названия и открой ворота.</p></div>${soundButton()}</header><div class="find-start__layout"><section class="find-start__story"><figure><img src="assets/games/find-animal-intro-gate.png" alt="Закрытые древние ворота с тайным кодом из китайских знаков"></figure><p>Перед животными выросли древние ворота, покрытые множеством китайских знаков. Только несколько из них складываются в тайный код, который открывает путь к дворцу. Когда весь код будет разгадан, ворота откроются.</p></section><section class="find-start__choice"><h2>Выбери уровень</h2><div class="find-mode-cards">${cards}</div><footer><div><p><b>Твой уровень:</b><span data-find-level>${level}</span></p><p><b>Жизни:</b><span aria-label="Три жизни">${lives}</span></p></div><button class="find-start__go" data-find-begin ${selected?'':'disabled'}>В путь <i>→</i></button></footer></section></div></main>`}
function sentenceStartScreen(){let selected=S.sentenceModeCandidate,modes=[['easy','易','Лёгкий','3–4 карточки, пиньинь и перевод'],['medium','中','Средний','4–5 карточек и одна лишняя'],['hard','难','Сложный','Задание на слух и две лишние карточки']],cards=modes.map((m,i)=>`<button class="sentence-start__mode ${selected===m[0]?'is-selected':''}" data-sentence-mode="${m[0]}" aria-pressed="${selected===m[0]}" style="--delay:${i+2}"><strong>${m[1]}</strong><span><b>${m[2]}</b><small>${m[3]}</small></span><em aria-hidden="true">✓</em></button>`).join(''),max=S.gameLives?.max||5,current=S.gameLives?.current??max,lives=Array.from({length:current},()=>`<img src="assets/ui/jade-guardian.png" alt="">`).join('');$('#app').innerHTML=`<main class="sentence-start"><header class="sentence-start__top"><button class="sentence-start__brand start-exit" data-view="home" aria-label="Выйти на главную">← Выйти</button><h1>Дворцовые ворота</h1>${soundButton()}</header><div class="sentence-start__layout"><section class="sentence-start__story"><figure><img src="assets/games/sentence-intro-gate.png" alt="Ворота дворца Нефритового императора с двенадцатью волшебными печатями"></figure><p>Животные добрались до дворца Нефритового императора, но ворота оказались заперты на двенадцать волшебных печатей. Собери все 12 предложений, найди двенадцать печатей и открой ворота дворца.</p></section><section class="sentence-start__choice"><h2>Выбери уровень</h2><div class="sentence-start__modes">${cards}</div><div class="sentence-start__actions"><div class="sentence-start__lives"><b>Жизни:</b><span aria-label="${current} из ${max}">${lives}</span></div><button class="sentence-start__go" data-sentence-begin ${selected?'':'disabled'}>В путь <i>→</i></button></div></section></div></main>`}
function findGameScreen(){$('#app').innerHTML=`<main class="find-game"><header class="find-game__top"><button class="find-game__exit" data-view="home">← Выйти</button><div><h1>Секретный код</h1><p>Найди спрятанные названия и открой ворота.</p></div>${soundButton()}${challengeLives()}</header><section id="gameStage" class="find-game__stage"></section></main>`;findGame();startMusic()}
function gameShell(){if(S.game===0&&!S.roadAnimal)return roadStartScreen();if(S.game===0)return roadGameScreen();if(S.game===1&&S.mode==='select')return sudokuStartScreen();if(S.game===1)return sudokuGameScreen();if(S.game===2){shadowGameScreen();shadows();startMusic();return}if(S.game===3&&S.mode==='select')return findStartScreen();if(S.game===3)return findGameScreen();if(S.game===4&&S.mode==='select')return sentenceStartScreen();let g=G[S.game];$('#app').innerHTML=shell(`<main class="game-page"><header class="game-top"><button class="jade-button" data-view="home">← Выйти</button><h1>${g[0]}</h1><div class="game-top__tools"><button class="rules-scroll" id="gameRules"><span>Правила игры</span></button><div class="game-meta" aria-label="Результаты текущей игры"><span class="game-stat" title="Очки за текущую игру">${mark('星')} <b data-game-score>${S.score}</b><small>очков</small></span><span class="game-stat game-stat--errors" title="Количество ошибок">Ошибки: <b data-game-errors>${S.errors}</b></span></div></div></header><section id="gameStage" class="stage paper"></section>${challengeLives()}</main>`);if(S.mode==='select')modeSelect();else GAME_RENDERERS[S.game]();startMusic()}
const MODES={1:[['easy','Лёгкий','Изображения животных, 4×4','图'],['medium','Средний','Иероглифы с пиньинем','兔 tù'],['hard','Сложный','Только иероглифы','兔']],3:[['easy','Лёгкий','Поле 6×6, пиньинь и прямые слова','词'],['hard','Сложный','Диагонали и ложные сочетания','字']],4:[['easy','Лёгкий','3–4 карточки, пиньинь и перевод','句'],['medium','Средний','4–5 карточек и одна лишняя','文'],['hard','Сложный','Задание на слух и две лишние карточки','听']]};
function modeSelect(){let intro=S.game===1?'Реши три разных поля.':S.game===3?'Найди все заданные названия.':'Собери четыре предложения.';$('#gameStage').innerHTML=`<div class="mode-select"><p>Перед началом игры</p><h2>Выбери режим</h2><p>${intro}</p><div class="modes">${MODES[S.game].map(m=>`<button class="mode" data-mode="${m[0]}"><span class="mode__icon">${m[3]}</span><h3>${m[1]}</h3><p>${m[2]}</p><b>Играть →</b></button>`).join('')}</div></div>`}
function startGame(i){S.game=i;S.view='game';S.mode=MODES[i]?'select':'play';S.step=0;S.score=0;S.errors=0;S.hints=0;S.attempts=0;S.lives=5;S.gameLives=GAME_LIFE_LIMITS[i]?{current:GAME_LIFE_LIMITS[i],max:GAME_LIFE_LIMITS[i],failed:false}:null;S.roadFailed=false;S.roadStarted=false;S.roadAnimal=null;S.roadCandidate=null;S.roadTasks=null;S.scrollSet=null;S.sudoku=null;S.sudokuModeCandidate=i===1?'easy':null;S.shadows=null;S.find=null;S.findModeCandidate=null;S.sentence=null;S.sentenceOrder=null;S.sentenceModeCandidate=null;render()}
const ROAD_POS=[[48,92],[54,88],[58,83],[54,78],[46,74],[41,69],[44,64],[53,60],[61,56],[64,51],[59,47],[51,44],[44,40],[40,36],[43,32],[50,29],[56,27],[61,23],[63,19],[59,15],[52,12],[45,9],[39,6],[49,2]];
