collection=function(){S.view='collection';let opened=A.filter(a=>animalStars(a.i)>0),fully=A.filter(a=>animalStars(a.i)===3),selected=A[S.collectionAnimal]||opened[0]||A[0],selectedStars=animalStars(selected.i),encounters=animalEncounters(selected.i),newAnimal=S.collectionNewAnimal;let medallions=A.map((a,i)=>{let stars=animalStars(a.i),open=stars>0,[x,y]=COLLECTION_POS[i];return `<button class="zodiac-medallion ${open?'is-open':'is-locked'} ${selected.i===a.i?'is-selected':''} ${stars===3?'is-complete':''} ${newAnimal===a.i?'is-new':''}" style="--x:${x}%;--y:${y}%" data-collection-animal="${a.i}" aria-label="${open?a.ru:'Неизвестное животное'}">${open?animalArt(a,'zodiac-medallion__animal'):'<b>?</b>'}<span>${'★'.repeat(stars)}</span></button>`}).join(''),dots=A.map(a=>`<i class="${animalStars(a.i)?'is-open':''}"></i>`).join(''),gameIcons=COLLECTION_GAME_META.map(([id,name,image])=>`<span class="collection-game-icon ${encounters[id]?'is-met':''}"><img src="${image}" alt=""><b>${name}</b>${encounters[id]?'<i>✓</i>':''}</span>`).join(''),stars=`${'★'.repeat(selectedStars)}${'☆'.repeat(3-selectedStars)}`,next=selectedStars===1?'Ещё две успешные встречи в других играх откроют все звёзды.':selectedStars===2?'Ещё одна успешная встреча в другой игре откроет третью звезду.':selectedStars>=3?'Животное изучено полностью.':'Успешно встреть это животное в одной из игр, чтобы открыть его.';$('#app').innerHTML=`<main class="zodiac-collection"><header><button class="zodiac-collection__back" data-view="home">◀ Назад</button><div><h1>Коллекция зодиака</h1><p>Открыто ${opened.length} из 12 <i>·</i> Изучено полностью ${fully.length} из 12 <button data-collection-help aria-label="Как работает коллекция">?</button></p><span class="zodiac-progress">${dots}</span></div>${soundButton()}</header><div class="zodiac-collection__layout"><section class="zodiac-wheel-large"><img src="assets/zodiac/zodiac-wheel-base.png" alt="Основа круга китайского Зодиака"><div>${medallions}</div></section><article class="zodiac-animal-card ${selectedStars?'':'is-locked'}">${selectedStars?`<h2>${selected.i+1}. ${selected.ru[0].toUpperCase()+selected.ru.slice(1)}</h2>${animalArt(selected,'zodiac-detail-animal')}<div class="zodiac-animal-name"><b>${selected.hanzi}</b><span>${selected.pinyin}</span><small>${selected.ru[0].toUpperCase()+selected.ru.slice(1)}</small></div><button class="jade-button speak" data-say="${selected.pinyin}">${mark('声')} Прослушать</button><hr><p>Встречи в путешествии</p><div class="collection-stars"><b>${stars}</b><span>${selectedStars} из 3</span></div><div class="collection-game-icons">${gameIcons}</div><small class="collection-next">${next}</small><button class="collection-where-button" data-collection-where>⌕ Где встретить?</button>`:`<h2>Неизвестное животное</h2><div class="zodiac-unknown">?</div><div class="collection-stars"><b>☆☆☆</b><span>0 из 3</span></div><p>${next}</p><button class="collection-where-button" data-collection-help>Как открыть?</button>`}</article></div><footer>ⓘ Успешно встречай животных в разных играх Нефритового пути — собирай звёзды и открывай весь Зодиак!</footer></main>`;if(newAnimal!=null){setTimeout(()=>{toast('Новое животное Зодиака!');sfx('success');S.collectionNewAnimal=null},250)}if(!S.collectionHelpSeen){S.collectionHelpSeen=true;save();setTimeout(collectionRules,350)}};
